INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('ai', 'en', 3, 'ai', 'AI engineering & secure AI adoption', 'AI-native IT, done safely.', 'MCP servers for your tools and data, agents that do real work, and the guardrails to adopt AI without leaking the company.', 'Talk AI', 'ai', 0, NULL, '[{"label":"AI engineering","text":"day rate on request"},{"label":"Workshops — see Consultancy & training"}]', '### What you get

- MCP servers built for your tools and data — exposed securely via Cloudflare (portals, Access, scoped tokens), manageable, auditable.
- AI agents and workflows that do real work inside your company: ticket triage, reporting, data entry, monitoring.
- Secure-AI consulting: AI acceptable-use policy, risk assessment of AI tools, data-leak prevention, prompt-injection-aware architecture.
- Training: *Coding with AI, securely* — hands-on workshops for developers and IT teams.
- Helping you become AI-native: which tools, which plan, which guardrails.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('apps', 'en', 1, 'apps', 'Custom web applications & websites', 'Modern, serverless, yours.', 'Stock management, back-office tools, portals, dashboards — and websites with your own CMS. No WordPress, no PHP, no hosting bill.', 'Describe your app', 'apps', 0, 750, '[{"label":"Website incl. own CMS/admin — one-off deliverable, no recurring fees","from":750},{"label":"Web application — depends on size and integrations","from":1500},{"label":"WordPress-to-serverless migration","from":750}]', '### What you get

- Custom web applications: stock management, back-office tools, customer portals, dashboards, internal apps.
- Websites with your own admin/CMS — no WordPress, no plugins, no PHP.
- Built on frameworks that are easy for AI to read and extend, so maintenance stays cheap forever.
- Hosted on serverless infrastructure (Cloudflare Workers) — fast, global, and no monthly hosting bill.
- Privacy engineered in: end-to-end encryption, data minimisation, EU-hosted services.
- You own the code and the repository. Always.

### WordPress rescue

Still paying for hosting, plugin updates and a theme that broke in 2019? I take your WordPress site and turn it into a modern app on serverless infrastructure. No more ugly pages, no more PHP, no more paid hosting. Same content, better everything.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('consultancy', 'en', 5, 'consultancy', 'Consultancy, training & NIS2 readiness', 'Your security department, part-time.', 'Security manager or SecOps engineer as a service, NIS2 and ISO 27001 gap analysis, vendor-neutral strategy, training.', 'Book a day', 'consultancy', 0, NULL, '[{"label":"Consultancy / SecOps / AI engineering","text":"day rate on request"},{"label":"Retainer — Security Manager as a service","text":"on request"},{"label":"Workshop / training — half day / full day","text":"on request"}]', '### What you get

- **IT Security Manager as a service** — a fixed number of days per month to own your security roadmap, vendors and policies.
- **SecOps engineer as a service** — hands-on operations on your stack.
- **NIS2 readiness** and **ISO 27001 gap analysis** — where you stand, what to fix first, what to document.
- Strategy & product selection: EDR/MDR, SIEM, IAM (Okta / Entra), SASE/Cloudflare, firewalls — vendor-neutral, based on having run them.
- Incident response readiness: playbooks, tabletop exercises, tooling.
- Zero Trust and identity architecture.
- **Training & awareness:** secure coding with AI, CTF-style workshops, phishing-awareness programmes, security basics for non-IT staff.

### NIS2

NIS2 is law in Belgium. If you''re in scope — or supply someone who is — you need to show you manage risk, not just buy products. I run the gap analysis, prioritise what actually matters, and leave you with a roadmap your management understands and an auditor accepts.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('hosting', 'en', 6, 'hosting', 'Managed hosting & operations', 'For the apps that need a server, I run the server.', 'EU datacenters, monitoring, patching, backups, first-line support. Per application, monthly.', 'Ask about hosting', 'apps', 1, NULL, '[{"label":"Managed hosting — per application, invoiced monthly","text":"on request"}]', 'For larger applications I build, I also run them: EU datacenters (Hetzner, Germany/Finland), monitoring, patching, backups, updates and first-line support. Priced per application, invoiced monthly. Not offered for third-party stacks.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('secops', 'en', 4, 'secops', 'Security operations automation & tooling', 'Security that runs itself.', 'Threat-intel pipelines, SIEM onboarding, detection engineering and Cloudflare Zero Trust — glue between the tools you already pay for.', 'Automate my SecOps', 'secops', 0, NULL, '[{"label":"SecOps automation & tooling","text":"project or day rate on request"}]', '### What you get

- Custom security tooling: dashboards, integrations, “glue” between the tools you already pay for.
- Threat-intelligence pipelines that turn the daily CVE firehose into *your* actionable list. Example: a new critical vulnerability is published, your vulnerability scanner is queried automatically, and you receive the list of affected servers within minutes, not weeks.
- SIEM onboarding, detection engineering, alert enrichment and automated response.
- Cloudflare Zero Trust implementation: replace the VPN with Tunnel + Access + Gateway, device posture, SaaS protection.
- Asset & identity hygiene automation.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('security', 'en', 2, 'security', 'Security assessments & penetration testing', 'Find it before someone else does.', 'Fixed-scope assessments of your AD, M365, identity and edge — or a scoped penetration test with retest included.', 'Request an assessment', 'security', 0, NULL, '[{"label":"Security assessment — fixed scope, report + remediation plan","text":"day rate on request"},{"label":"Penetration test — scoped, rules of engagement, retest included","text":"day rate on request"}]', '### 2a. Security assessment

Fixed scope, report and remediation plan.

- Active Directory health (PingCastle-style scoring and hardening plan).
- Microsoft Entra / M365 configuration review (Maester-style automated checks + manual review).
- Identity & access review: MFA coverage, conditional access, privileged accounts.
- Cloudflare / network edge configuration.
- Endpoint & patching posture.
- Deliverable: prioritised findings, risk rating, concrete remediation steps you can hand to any IT provider.

### 2b. Penetration test

Scoped, with rules of engagement, retest included.

- External perimeter, web application, internal / Active Directory.
- Deliverable: executive summary + technical report + retest of fixed findings.
- Penetration tests are delivered under a formal engagement framework with rules of engagement and insurance in place.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('ai', 'nl', 3, 'ai', 'AI-engineering & veilige AI-adoptie', 'AI-native IT, veilig gedaan.', 'MCP-servers voor je tools en data, agents die echt werk doen, en de vangrails om AI in te voeren zonder het bedrijf te lekken.', 'Praat over AI', 'ai', 0, NULL, '[{"label":"AI-engineering","text":"dagtarief op aanvraag"},{"label":"Workshops — zie Consultancy & training"}]', '### Wat je krijgt

- MCP-servers gebouwd voor jouw tools en data — veilig ontsloten via Cloudflare (portalen, Access, scoped tokens), beheerbaar, auditeerbaar.
- AI-agents en workflows die echt werk doen in je bedrijf: tickettriage, rapportering, data-invoer, monitoring.
- Secure-AI consulting: AI-gebruiksbeleid, risicobeoordeling van AI-tools, datalekpreventie, architectuur die prompt-injectie meeneemt.
- Training: *Coderen met AI, veilig* — hands-on workshops voor developers en IT-teams.
- Je helpen AI-native te worden: welke tools, welk plan, welke vangrails.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('apps', 'nl', 1, 'apps', 'Webapplicaties & websites op maat', 'Modern, serverless, van jou.', 'Voorraadbeheer, back-office tools, portalen, dashboards — en websites met je eigen CMS. Geen WordPress, geen PHP, geen hostingfactuur.', 'Beschrijf je app', 'apps', 0, 750, '[{"label":"Website incl. eigen CMS/admin — eenmalige oplevering, geen terugkerende kosten","from":750},{"label":"Webapplicatie — afhankelijk van omvang en integraties","from":1500},{"label":"Migratie van WordPress naar serverless","from":750}]', '### Wat je krijgt

- Webapplicaties op maat: voorraadbeheer, back-office tools, klantenportalen, dashboards, interne apps.
- Websites met je eigen admin/CMS — geen WordPress, geen plugins, geen PHP.
- Gebouwd op frameworks die AI makkelijk kan lezen en uitbreiden, zodat onderhoud voor altijd goedkoop blijft.
- Gehost op serverless infrastructuur (Cloudflare Workers) — snel, wereldwijd, en geen maandelijkse hostingfactuur.
- Privacy ingebouwd: end-to-end encryptie, dataminimalisatie, diensten gehost in de EU.
- De code en de repository zijn van jou. Altijd.

### WordPress-redding

Betaal je nog voor hosting, plugin-updates en een thema dat in 2019 brak? Ik neem je WordPress-site en maak er een moderne app van op serverless infrastructuur. Geen lelijke pagina''s meer, geen PHP meer, geen betaalde hosting meer. Dezelfde inhoud, alles beter.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('consultancy', 'nl', 5, 'consultancy', 'Consultancy, training & NIS2-readiness', 'Je securityafdeling, deeltijds.', 'Security manager of SecOps engineer as a service, NIS2- en ISO 27001-gap-analyse, leveranciersneutrale strategie, training.', 'Boek een dag', 'consultancy', 0, NULL, '[{"label":"Consultancy / SecOps / AI-engineering","text":"dagtarief op aanvraag"},{"label":"Retainer — Security Manager as a service","text":"op aanvraag"},{"label":"Workshop / training — halve dag / hele dag","text":"op aanvraag"}]', '### Wat je krijgt

- **IT Security Manager as a service** — een vast aantal dagen per maand om je securityroadmap, leveranciers en beleid te dragen.
- **SecOps engineer as a service** — hands-on operations op jouw stack.
- **NIS2-readiness** en **ISO 27001-gap-analyse** — waar je staat, wat eerst te fixen, wat te documenteren.
- Strategie & productkeuze: EDR/MDR, SIEM, IAM (Okta / Entra), SASE/Cloudflare, firewalls — leveranciersneutraal, gebaseerd op ze zelf gedraaid te hebben.
- Incident-response readiness: playbooks, tabletop-oefeningen, tooling.
- Zero Trust- en identity-architectuur.
- **Training & bewustwording:** veilig coderen met AI, CTF-workshops, phishing-bewustwordingsprogramma''s, securitybasis voor niet-IT-medewerkers.

### NIS2

NIS2 is wet in België. Val je onder de scope — of lever je aan iemand die eronder valt — dan moet je aantonen dat je risico beheert, niet alleen dat je producten koopt. Ik doe de gap-analyse, prioriteer wat er echt toe doet, en laat je achter met een roadmap die je management begrijpt en een auditor aanvaardt.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('hosting', 'nl', 6, 'hosting', 'Managed hosting & operations', 'Voor apps die een server nodig hebben, draai ik de server.', 'EU-datacenters, monitoring, patching, back-ups, eerstelijnssupport. Per applicatie, maandelijks.', 'Vraag naar hosting', 'apps', 1, NULL, '[{"label":"Managed hosting — per applicatie, maandelijks gefactureerd","text":"op aanvraag"}]', 'Grotere applicaties die ik bouw, draai ik ook: EU-datacenters (Hetzner, Duitsland/Finland), monitoring, patching, back-ups, updates en eerstelijnssupport. Prijs per applicatie, maandelijks gefactureerd. Niet aangeboden voor stacks van derden.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('secops', 'nl', 4, 'secops', 'Automatisering van security operations', 'Security die zichzelf draait.', 'Threat-intel pipelines, SIEM-onboarding, detection engineering en Cloudflare Zero Trust — lijm tussen de tools waar je al voor betaalt.', 'Automatiseer mijn SecOps', 'secops', 0, NULL, '[{"label":"SecOps-automatisering & tooling","text":"project- of dagtarief op aanvraag"}]', '### Wat je krijgt

- Security tooling op maat: dashboards, integraties, "lijm" tussen de tools waar je al voor betaalt.
- Threat-intelligence pipelines die de dagelijkse CVE-stroom omzetten in *jouw* actielijst. Voorbeeld: een nieuwe kritieke kwetsbaarheid wordt gepubliceerd, je vulnerability scanner wordt automatisch bevraagd, en je krijgt de lijst van getroffen servers binnen minuten, niet weken.
- SIEM-onboarding, detection engineering, alertverrijking en geautomatiseerde respons.
- Cloudflare Zero Trust-implementatie: vervang de VPN door Tunnel + Access + Gateway, device posture, SaaS-bescherming.
- Automatisering van asset- en identity-hygiëne.');
INSERT OR IGNORE INTO services (anchor, lang, sort, icon, title, headline, summary, cta, cta_topic, secondary, card_price, prices, body) VALUES ('security', 'nl', 2, 'security', 'Security assessments & penetratietesten', 'Vind het voor iemand anders het vindt.', 'Assessments met vaste scope van je AD, M365, identity en edge — of een afgebakende penetratietest met hertest inbegrepen.', 'Vraag een assessment aan', 'security', 0, NULL, '[{"label":"Security assessment — vaste scope, rapport + remediatieplan","text":"dagtarief op aanvraag"},{"label":"Penetratietest — afgebakend, rules of engagement, hertest inbegrepen","text":"dagtarief op aanvraag"}]', '### 2a. Security assessment

Vaste scope, rapport en remediatieplan.

- Active Directory-gezondheid (PingCastle-achtige score en hardeningplan).
- Microsoft Entra / M365-configuratiereview (Maester-achtige geautomatiseerde checks + manuele review).
- Identity & access review: MFA-dekking, conditional access, bevoorrechte accounts.
- Cloudflare / netwerk-edge configuratie.
- Endpoint- en patchingposture.
- Resultaat: geprioriteerde bevindingen, risicoscore, concrete remediatiestappen die je aan elke IT-leverancier kan geven.

### 2b. Penetratietest

Afgebakend, met rules of engagement, hertest inbegrepen.

- Externe perimeter, webapplicatie, intern / Active Directory.
- Resultaat: managementsamenvatting + technisch rapport + hertest van de opgeloste bevindingen.
- Penetratietesten worden geleverd binnen een formeel engagementkader met rules of engagement en verzekering.');
